internal fun nativeCallSafetyEmojis(code:String):String {
    val hex=code.filter{it in "0123456789abcdefABCDEF"};if(hex.length!=16)return ""
    val bytes=hex.chunked(2).map{it.toInt(16)}
    return (0 until 4).joinToString(" "){CallSafetyEmoji[bytes[it] xor bytes[it+4]]}
}
